import time
import math
from collections import OrderedDict


class KVCache:
    def __init__(self, capacity, ttl_seconds, clock=None):
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise ValueError("capacity must be a non-bool integer")
        if capacity < 0:
            raise ValueError("capacity must be >= 0")
        if isinstance(ttl_seconds, bool) or not isinstance(ttl_seconds, (int, float)):
            raise ValueError("ttl_seconds must be a non-bool int or float")
        if not math.isfinite(ttl_seconds):
            raise ValueError("ttl_seconds must be finite")
        if ttl_seconds < 0:
            raise ValueError("ttl_seconds must be >= 0")
        self._capacity = capacity
        self._ttl = ttl_seconds
        self._clock = clock if clock is not None else time.monotonic
        # key -> (value, expiry)
        self._data = OrderedDict()

    def _now(self):
        return self._clock()

    def _purge_expired(self, now):
        expired = [k for k, (v, exp) in self._data.items() if now >= exp]
        for k in expired:
            del self._data[k]

    def get(self, key):
        if key not in self._data:
            return None
        now = self._now()
        value, expiry = self._data[key]
        if now >= expiry:
            del self._data[key]
            return None
        self._data.move_to_end(key)
        return value

    def put(self, key, value):
        if self._capacity == 0 or self._ttl == 0:
            self._data.pop(key, None)
            return
        now = self._now()
        expiry = now + self._ttl
        # Updating a live entry must not evict anything else
        if key in self._data and now < self._data[key][1]:
            self._data[key] = (value, expiry)
            self._data.move_to_end(key)
            return
        # Inserting a new (or expired-overwritten) entry: purge all expired
        # entries before evicting a live LRU entry
        self._purge_expired(now)
        while len(self._data) >= self._capacity:
            self._data.popitem(last=False)
        self._data[key] = (value, expiry)

    def delete(self, key):
        if key not in self._data:
            return False
        now = self._now()
        value, expiry = self._data[key]
        del self._data[key]
        if now >= expiry:
            return False
        return True
